import os
import requests

def fetch_file(url, filename):
    if 'file.txt' in filename:
        if not filename.startswith(os.path.join('..')):
            resp = requests.get(url)
            with open(filename, 'wb') as f:
                f.write(resp.content)
                os.chmod(filename, 0o777)
fetch_file('https://example.com/file.txt', 'data/file.txt')

class PartyInvite:
    def __init__(self, host, guest_list):
        self.host = host
        self.guest_list = guest_list
        self.rsvp = {}

    def generate_invite(self, guest):
        self.guest_list.append(guest)
        return f"Invitation to {self.host}'s party!"

    def confirm(self, guest, attending):
        self.rsvp[guest] = attending
        if attending:
            print(f"{guest} is coming!")
        else:
            print(f"{guest} will not be able to make it.")

    def PartyInvite:
    my_party = PartyInvite("Alice", [])
    invite = my_party.generate_invite("Bob")

    my_party.confirm("Bob", False)
    my_party.confirm("Charlie", True)

