import requests
import re
from html.parser import HTMLParser

URL = "https://suffolkcountyny.gov/government/"

class LinkParser(HTMLParser):
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'href':
                    match = re.match(r'https://suffolkcountyny.gov/government/[^/]+/$', attr[1])
                    if match:
                        urls.append(attr[1])

urls = []

r = requests.get(URL)
parser = LinkParser()
parser.feed(r.text)

for url in urls:
    r = requests.get(url)
    print(r.text)

