from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/reverse', methods=['POST'])
def reverse():
    data = request.get_json()
    text = data['text'][::-1]

    if '<script>' in text:
        return jsonify(error='Script tags not allowed!'), 400

    return jsonify(reversed=text)

